package com.clinic.appointment.controller;import com.clinic.appointment.service.AppointmentService.SlotConflictException;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(SlotConflictException.class)@ResponseStatus(HttpStatus.CONFLICT)Map<String,Object> conflict(Exception e){return err("SLOT_CONFLICT",e);}@ExceptionHandler(NoSuchElementException.class)@ResponseStatus(HttpStatus.NOT_FOUND)Map<String,Object> missing(Exception e){return err("NOT_FOUND",e);}@ExceptionHandler(SecurityException.class)@ResponseStatus(HttpStatus.FORBIDDEN)Map<String,Object> forbidden(Exception e){return err("ACCESS_DENIED",e);}@ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class})@ResponseStatus(HttpStatus.BAD_REQUEST)Map<String,Object> bad(Exception e){return err("INVALID_REQUEST",e);}private Map<String,Object> err(String c,Exception e){return Map.of("timestamp",Instant.now(),"code",c,"message",e.getMessage());}}
